export const coldClimateGuides: ColdClimateGuide[] = [
  {
    slug: 'natural-stone-freeze-thaw-climates-usa',
    title: 'Natural Stone for Freeze–Thaw Climates: A US Buyer’s Guide',
    metaDescription: 'Choose natural stone for cold US climates. Compare exposure, test reports, drainage, finishes and sample approvals for patios, veneer and exterior walls.',
    keywords: 'natural stone freeze thaw, cold climate stone, exterior stone USA, frost resistant stone specification',
    summary: 'Choose exterior stone by its documented performance in the proposed assembly, not its color or rock name alone. In a freezing climate, moisture exposure, drainage, finish and installation matter alongside the stone itself.',
    category: 'Cold Climate Guide', image: claddingImage, imageAlt: 'Illustration of natural stone exterior wall cladding', productIds: ['q4', 'q2', 's4', 's6'], stoneCategories: ['quartzite', 'sandstone', 'limestone', 'slate'],
    sections: [
      { id: 'exposure', title: 'Start with the exposure, not a blanket “frostproof” label', html: `<p>A front wall under a deep roof in Vermont, an open patio in Michigan and a pool coping in Minnesota experience different combinations of water, ice and wear. A stone that works well as protected vertical cladding is not automatically the right choice for a saturated horizontal surface. Write down where water arrives, where it can collect and how it leaves before comparing colors.</p><p>For a northern US project, record the installation position, snow storage areas, contact with deicers, splash from roofs, expected traffic and whether the surface will be heated. New England, the Great Lakes and mountain regions are useful planning contexts, but a regional name cannot replace the conditions at the actual site.</p>` },
      { id: 'shortlist', title: 'Build a shortlist from the real product range', html: `<p><a href="/products?category=quartzite">Quartzite</a> offers textured and crystalline appearances for walls and selected exterior surfaces. <a href="/products?category=sandstone">Sandstone</a> provides warm and neutral paving colors, including Kandla Grey and Buff. <a href="/products?category=limestone">Limestone</a> gives a more even visual field, while <a href="/products?category=slate">slate</a> offers a layered appearance. These are design choices to investigate, not a ranking of guaranteed winter performance.</p><p>Compare actual samples in the specified thickness and finish. A photograph cannot show how a riven edge feels underfoot, how a dark surface looks when wet, or whether the batch includes an acceptable range of natural variation. For wall projects, include <a href="/thin-stone-veneer">rigid veneer, flexible panels and random-pattern designs</a> in the conversation as distinct constructions.</p>` },
      { id: 'evidence', title: 'Ask for evidence that matches the stone and the use', html: `<p>A useful technical submission identifies the stone source, sample, thickness, finish, test method, date and laboratory. Ask the supplier which reports are available for the proposed material, then have the project specifier decide whether more testing is needed. An absorption result by itself is not a complete freeze–thaw assessment.</p><ul><li>Water absorption and density help characterize the material.</li><li>Strength and abrasion information should match the intended load and traffic.</li><li>Environmental exposure testing should address the proposed freezing and moisture conditions.</li><li>Bond, backing and attachment information matter when the stone is supplied as a panel or veneer system.</li></ul><p>Never copy a result from another quarry or from a generic internet table into a purchase order. Roop Stone Impex can discuss available documentation with your enquiry; final acceptance criteria belong in the agreed project specification.</p>` },
      { id: 'assembly', title: 'Design for water to leave the assembly', html: `<p>A durable wall starts behind the visible face. Coordinate drainage, flashing, terminations, penetrations and compatible attachment with the wall designer. A stone-faced wall should not rely on the face material alone to stop water. On paving, review the base, drainage route, edge restraint and finished levels with the installer.</p><p>Consider the snow-clearing plan while the design is still flexible. Concentrated roof runoff, a snow pile against the base of a wall or a low point beside a door may create more demanding exposure than the rest of the project. A more expensive stone does not correct trapped water or an unsuitable substrate.</p>` },
      { id: 'rfq', title: 'Send a purchase brief the supplier can quote accurately', html: `<p>Include destination ZIP code, use, measured quantity, preferred stone, finish, thickness, dimensional tolerance and installation method. Add drawings for corners, caps, tread noses and other custom pieces. Ask for sample approval, packing details and the required technical submission before the balance of the order is produced.</p><p>For example, a Massachusetts exterior-wall enquiry should describe the backing and veneer construction, whereas a Wisconsin patio enquiry should describe the paving format, base and snow-maintenance plan. Use our <a href="/pricing">FOB price guide</a> for an initial material comparison, then request a project quotation with destination logistics separated from the stone price.</p>` },
    ],
    faqs: [
      { question: 'Is all quartzite frost resistant?', answer: 'A rock name alone does not establish performance. Evaluate the actual stone, finish, thickness, exposure and relevant test documentation for the proposed installation.' },
      { question: 'Does sealing make a stone suitable for freezing weather?', answer: 'Sealing does not replace material selection, testing or drainage. Choose any treatment with the stone and treatment suppliers for the actual application.' },
      { question: 'Can I use the same stone on a wall and a patio?', answer: 'Possibly, but assess the two uses separately. Horizontal paving has different moisture, loading, wear and traction requirements from vertical veneer.' },
    ], sources: [stoneSources.testing, stoneSources.drainage],
  },
  {
    slug: 'thin-stone-veneer-cold-climate-exteriors',
    title: 'Thin Stone Veneer for Cold Climates: Rigid Pieces or Flexible Panels?',
    metaDescription: 'Compare rigid thin stone veneer and flexible stone panels for cold-climate projects, with questions on backing, thickness, drainage, joints and samples.',
    keywords: 'thin stone veneer cold climates, flexible stone panels, natural stone veneer exterior, rigid stone veneer',
    summary: 'Rigid natural stone veneer and flexible stone panels are different products. Select the construction first, then confirm the backing, thickness, attachment and exterior exposure requirements for the complete assembly.',
    category: 'Veneer & Panels', image: veneerImage, imageAlt: 'Natural stone veneer panel design from the Roop Stone Impex collection', productIds: [], stoneCategories: ['mosaic', 'quartzite', 'slate'],
    sections: [
      { id: 'two-products', title: 'Two products share the name “thin stone veneer”', html: `<p>US buyers use “thin stone veneer” for more than one construction. Rigid veneer consists of individual stone pieces or assembled panels with a reduced bed depth. Flexible veneer combines a thin natural stone face with a backing. The backing, adhesive and joint treatment form part of its performance; the face stone alone does not describe the product.</p><p>Roop Stone Impex makes rigid natural stone pieces and flexible panels, including custom patterns. The <a href="/thin-stone-veneer">veneer collection</a> explains these options separately. Send the design reference and intended use so the quotation identifies which construction is being offered.</p>` },
      { id: 'thickness', title: 'Use example thicknesses to start a discussion, not to order', html: `<p>Published examples from other manufacturers show rigid ledgestone at about 1 inch (25 mm), while a flexible veneer datasheet lists approximately 1.5–2.5 mm total thickness. These examples illustrate the large difference between product types. They are not Roop Stone Impex specifications, a universal standard or interchangeable wall systems.</p><p>For a custom order, confirm total thickness, relief depth, backing, unit weight, panel size and tolerances on the approved drawing. A sculptural surface can have a shallow back and a much deeper face. Ask whether a stated dimension measures the backing, average bed depth or highest point of the texture.</p>` },
      { id: 'winter-wall', title: 'Check the whole exterior assembly for winter exposure', html: `<p>A flexible panel intended for an interior feature wall should not be substituted into an exposed freezing facade without the required product and assembly approval. Likewise, a rigid natural stone face does not establish the suitability of a mesh, resin, mortar or adhesive behind it. Review temperature range, moisture exposure, bond, movement and substrate compatibility together.</p><p>Have the wall designer coordinate the water-resistive layer, drainage, flashings and transitions. Plan what happens at the bottom of the veneer, at windows and above doors. Water that enters at an unfinished top edge can affect a far larger area than the visible opening.</p>` },
      { id: 'patterns', title: 'Choose a pattern that can be detailed consistently', html: `<p>Linear panels create horizontal courses; random or crazy-pattern stone uses irregular outlines and a less repetitive composition. Both can work in high-end architecture, but their setting-out and joint decisions differ. Request a sufficiently large dry layout or mock-up to see repeated shapes, color distribution and corner transitions.</p><p>Where a facade turns a corner, decide whether the design uses purpose-made corner pieces, returns or a documented joint detail. Avoid showing a thick-looking stone edge in a rendering if the supplied assembly has a different edge construction. Approve the physical sample with the drawing.</p>` },
      { id: 'quote-checklist', title: 'What to include in a veneer enquiry', html: `<ul><li>Rigid individual pieces, assembled panels or flexible sheets.</li><li>Interior, sheltered exterior or fully exposed exterior location.</li><li>Stone color and desired panel or random-pattern reference.</li><li>Substrate, attachment method, thickness and weight constraints.</li><li>Flat area, corners, openings, returns and custom caps.</li><li>Destination, programme, sample requirements and requested documentation.</li></ul><p>Keep each product type on its own quote line. This makes it possible to compare the supplied construction and packing, instead of comparing two prices for products that happen to share the word “veneer.”</p>` },
    ], faqs: [
      { question: 'Are flexible stone sheets the same as rigid stone panels?', answer: 'No. Flexible sheets use a thin natural stone face and a backing. Rigid panels or pieces have a different construction, weight and installation method.' },
      { question: 'Does Roop Stone Impex offer custom veneer thicknesses?', answer: 'Roop Stone Impex makes custom stone work. Confirm the construction, thickness, tolerances and application in the quotation and approved sample.' },
      { question: 'Can all flexible panels be installed outdoors?', answer: 'Exterior use depends on the specific backing, adhesive, substrate, joint detailing and documented exposure suitability. Confirm the complete system before ordering.' },
    ], sources: [stoneSources.flexible, stoneSources.rigid, stoneSources.drying],
  },
  {
    slug: 'random-crazy-pattern-stone-wall-cladding',
    title: 'Random and Crazy-Pattern Stone Cladding for Custom Facades',
    metaDescription: 'Specify random-pattern natural stone walls: choose piece scale, joints, colors, corners and mock-ups for custom facades and high-end interiors.',
    keywords: 'random stone wall cladding, crazy pattern stone veneer, irregular stone facade, custom natural stone panels',
    summary: 'A successful random-pattern stone wall has a deliberate layout. Approve the size distribution, joint width, color blend and corner treatment in a physical mock-up before ordering the full facade.',
    category: 'Veneer & Panels', image: randomImage, imageAlt: 'Roop Stone Impex decorative natural stone cladding design', productIds: [], stoneCategories: ['mosaic', 'sandstone', 'quartzite', 'slate'],
    sections: [
      { id: 'define-pattern', title: 'Define what “random” means for the project', html: `<p>Random stone, irregular stone and crazy-pattern cladding describe a visual approach rather than one standardized product. A drawing may show loose pieces fitted on site, pre-arranged panels or a custom pattern cut to a numbered layout. Tell the fabricator which result you expect. The same stone color can look restrained in large pieces and much busier in a small, tightly mixed pattern.</p><p>For a hotel entrance, a residential facade or an interior reception wall, begin with the viewing distance. A fine pattern that looks attractive in a close-up may disappear across a courtyard. Conversely, large blocks can overwhelm a narrow fireplace return. Review the full elevation as well as the sample board.</p>` },
      { id: 'design-controls', title: 'Set four controls before selecting the final stone', html: `<p><strong>Piece scale:</strong> define the range of small, medium and large pieces rather than ordering “mixed sizes.” <strong>Joint appearance:</strong> decide on open-looking, recessed or pointed joints with the installer. <strong>Color blend:</strong> approve the balance of base tones and accent pieces. <strong>Surface depth:</strong> review how the relief will catch daylight and artificial light.</p><p>Specify whether the pattern should appear coursed, loosely interlocking or deliberately free-form. Ask how repetitive units will be distributed if the product is panelized. A panel system can simplify setting-out, but the joins should still be reviewed at the scale of the whole wall.</p>` },
      { id: 'mockup', title: 'Use a mock-up to approve variation and workmanship', html: `<p>A single hand sample confirms very little about a random wall. Request a larger arrangement with the proposed color range, typical joints and at least one corner or opening edge. Photograph it in even daylight and with the intended grazing light. Include a scale reference so the visual approval cannot be confused with a different piece size.</p><p>Agree how the mock-up will be used during production and installation. Record the acceptable range of shade, face texture, edge treatment and joint width. The objective is a repeatable design language, not identical natural stones.</p>` },
      { id: 'exterior-detailing', title: 'Resolve edges and weather exposure before production', html: `<p>For exposed walls in northern US or other cold markets, coordinate the top termination, window returns, wall base and drainage with the project designer. A random layout should not leave the installer improvising the most exposed edges. Individual pieces, rigid panels and flexible sheets need their own compatible attachment and transition details.</p><p>Do not use a decorative wall-panel specification for a walking surface. If the same visual idea extends onto a path, develop a separate paving specification with appropriate thickness, support and surface requirements. This distinction is especially important where ice, snow clearing and concentrated foot traffic are expected.</p>` },
      { id: 'custom-order', title: 'Prepare a custom fabrication package', html: `<p>Send elevation drawings, measured dimensions, openings, corner lengths and photographs of the site. Identify the stone family, color reference, surface depth and whether fabrication should follow a numbered layout. Include access constraints and the sequence in which areas will be installed so crates can be labeled accordingly.</p><p>Our <a href="/thin-stone-veneer">stone veneer and custom panel range</a> includes rigid pieces and flexible panels. Use the enquiry to agree the construction and sample first. For a coordinated building palette, compare the veneer with <a href="/products?category=sandstone">sandstone paving</a> or <a href="/products?category=quartzite">quartzite feature stone</a>, while specifying each application separately.</p>` },
    ], faqs: [
      { question: 'Does crazy-pattern stone mean loose stone or panels?', answer: 'It can mean either. Confirm whether the design uses individual pieces, pre-arranged rigid panels or a custom sheet/panel construction before comparing quotations.' },
      { question: 'Can the pattern be made to an architect’s drawing?', answer: 'Roop Stone Impex offers custom fabrication. Submit drawings, pattern references, construction details and sample requirements for review and quotation.' },
    ], sources: [stoneSources.drainage],
  },
  {
    slug: 'quartzite-wall-cladding-northeast-usa',
    title: 'Quartzite Wall Cladding for Northeast US Homes: A Specifier’s Guide',
    metaDescription: 'Compare Deoli Green, Silver Shine and Silver Grey quartzite for Northeast US walls, with guidance on samples, finishes, exposure and facade detailing.',
    keywords: 'quartzite wall cladding USA, Deoli Green exterior, Silver Shine stone veneer, Northeast stone facade',
    summary: 'For a Northeast US wall, select the quartzite’s color and texture alongside its construction and exposure details. Request material-specific documentation and a sample in the intended finish before approving the facade.',
    category: 'Product Selection', image: deoliImage, imageAlt: 'Deoli Green natural quartzite product sample', productIds: ['q4', 'q2', 'q3', 'q7'], stoneCategories: ['quartzite'],
    sections: [
      { id: 'palette', title: 'Compare the palette against the whole building', html: `<p><a href="/products/q4">Deoli Green</a> brings a deep green character to a facade or feature wall. <a href="/products/q2">Silver Shine</a> offers a more reflective silver-toned appearance, while <a href="/products/q3">Silver Grey</a> supports a quieter gray palette. Choose the tone beside the actual window frames, roofing, metalwork and surrounding landscape rather than from an isolated screen image.</p><p>For a home in New York, Massachusetts or a northern inland location, look at the sample in overcast light as well as direct sun. A finish that looks lively in strong light can appear flatter on a shaded elevation. Wetting an approval sample can also help the design team understand a possible appearance change, without being a durability test.</p>` },
      { id: 'format-finish', title: 'Specify format and finish together', html: `<p>A natural cleft face emphasizes texture. A honed or polished surface creates a different visual effect and fabrication requirement. Panel size, edge treatment and thickness should be coordinated with the attachment and support system. Do not choose a large format solely because a smaller hand sample looks attractive.</p><p>Decide whether the design is solid stone cladding, a rigid veneer panel or a flexible stone-faced product. These options can share a similar color family while requiring different installation details. Ask for the product construction in writing and review how it terminates at exposed edges.</p>` },
      { id: 'submission', title: 'Build a useful technical submission', html: `<p>Request the documentation available for the selected variety and intended use. The submission should identify what was tested, not simply list the name of an ASTM method. Where freezing exposure is relevant, the designer should decide which environmental testing and assembly information are needed.</p><p>Include the proposed finish and thickness, attachment method, backing if applicable, and how the stone will be supported around openings. A generic category statement such as “quartzite is hard” does not resolve the requirements for a particular facade. See our <a href="/blog/natural-stone-freeze-thaw-climates-usa">freeze–thaw selection guide</a> for a purchase checklist.</p>` },
      { id: 'junctions', title: 'Draw the junctions that are easy to overlook', html: `<p>Review window heads, sills, roof-to-wall transitions, doors, vents, corners and the base of the cladding. Coordinate flashings and the drainage path with the wall assembly. Keep future maintenance access in mind where gutters, downpipes or snow accumulation may concentrate water.</p><p>A dramatic stone wall can still have a simple, repeatable installation sequence. Numbered elevations, documented corners and agreed joint locations reduce decisions left to the site team. Approve a mock-up that shows at least one transition, rather than only a flat face.</p>` },
      { id: 'order', title: 'Order a consistent visual range', html: `<p>Ask the supplier to show the range of natural color variation and discuss how material will be distributed across the elevation. If the facade has several phases, plan the quantity together instead of assuming that a later shipment will match an early selection exactly. Keep an agreed reference sample and photographs with the project documents.</p><p>Send Roop Stone Impex your elevation, location, quantity and preferred <a href="/products?category=quartzite">quartzite varieties</a>. We can discuss custom fabrication and the appropriate submission for review. Compare the final installed specification and delivery scope alongside price.</p>` },
    ], faqs: [
      { question: 'Is Deoli Green suitable for every Northeast exterior?', answer: 'Suitability must be assessed for the actual stone product, exposure and wall assembly. Review the available documentation, thickness, finish and attachment with the project specifier.' },
      { question: 'Should all elevations use the same finish?', answer: 'That is a design and technical decision. Review lighting, exposure, fabrication and maintenance for each location, and approve samples of every specified finish.' },
    ], sources: [stoneSources.testing, stoneSources.drainage],
  },
  {
    slug: 'kandla-grey-buff-sandstone-patios-northern-usa',
    title: 'Kandla Grey or Buff Sandstone for a Northern US Patio?',
    metaDescription: 'Compare Kandla Grey and Buff sandstone patio designs for northern US projects. Review samples, paving thickness, finish, drainage and winter maintenance.',
    keywords: 'Kandla Grey sandstone USA, buff sandstone patio, sandstone paving cold climate, northern USA patio stone',
    summary: 'Kandla Grey and Buff are color choices, not winter-performance ratings. Compare the actual paving product, finish, thickness and evidence, then coordinate the base, drainage and maintenance plan for the site.',
    category: 'Product Selection', image: pavingImage, imageAlt: 'Illustration of natural sandstone patio paving', productIds: ['s4', 's6', 's18', 's8'], stoneCategories: ['sandstone'],
    sections: [
      { id: 'appearance', title: 'Choose the color with the house and landscape', html: `<p><a href="/products/s4">Kandla Grey sandstone</a> creates a neutral setting for timber, planting and contemporary metalwork. <a href="/products/s6">Buff sandstone</a> brings a warmer cream-toned palette. Both deserve a physical comparison against the surrounding brick, siding, steps and garden furniture.</p><p>Use several pieces rather than one small sample to judge the natural variation. In a northern garden, compare the proposed paving on a bright day and under flatter winter light. If you are matching a photograph, tell the supplier which part of the image matters: the base color, the range of shades, the surface texture or the joint pattern.</p>` },
      { id: 'paving-specification', title: 'Order paving, not an unspecified stone tile', html: `<p>The application should lead the specification. Tell the supplier whether the patio is pedestrian-only, whether equipment will cross it and how the units will be supported. Agree the dimensions, thickness, calibration, edge treatment and tolerances with the installer. A wall-cladding piece is not a paving specification.</p><p>Choose the layout before ordering. A modular design needs a consistent relationship between stone dimensions and joint widths. Large slabs, mixed-size packs and small units can create different installation and handling requirements even when their total square footage is identical.</p>` },
      { id: 'weather', title: 'Evaluate winter conditions before approving the stone', html: `<p>Ask for available documentation relevant to the proposed paving. Do not treat the word “Indian,” a quarry region or a color name as proof of freeze–thaw performance. The selected material and the intended wetting, freezing and deicer exposure need to be considered together.</p><p>For Michigan, Wisconsin, New England or another freezing location, identify shaded areas, roof discharge and snow-storage zones on the plan. A patio can have one persistent wet low point even when the rest dries well. See the <a href="/blog/natural-stone-freeze-thaw-climates-usa">cold-climate stone guide</a> before comparing final quotations.</p>` },
      { id: 'installation', title: 'Coordinate the base, water route and surface finish', html: `<p>The contractor should design the base and drainage for the site, soil and intended use. Review levels at doors, where water exits, and transitions to lawn, drains and adjacent paving. Edge support and movement details also belong in the installation scope. A material quote by itself does not include these decisions.</p><p>Review the proposed finish for wet use, cleanability and traction. A textured appearance alone is not a documented slip rating, and ice can make any walking surface hazardous. Confirm the snow-clearing tools and maintenance approach before the first winter.</p>` },
      { id: 'samples-ordering', title: 'Turn the choice into an accurate order', html: `<p>Send the patio plan, finish, quantity, dimensions, thickness and destination ZIP code with your enquiry. List steps, copings and edge pieces separately. Discuss an allowance for cuts and future repairs with the installer rather than applying a fixed waste percentage to every layout.</p><p>Approve the sample range and packing before production. Our <a href="/pricing">sandstone price guide</a> is a starting point for the material cost; ask for a quotation that distinguishes stone, fabrication and shipping. For a warmer alternative, compare <a href="/products/s18">Autumn Brown</a> or <a href="/products/s8">Dholpur Beige</a> using the same selection process.</p>` },
    ], faqs: [
      { question: 'Is Buff sandstone less suitable for winter because it is lighter?', answer: 'Color is not a winter-performance rating. Evaluate the actual material and installation with relevant technical information.' },
      { question: 'Is a natural riven surface automatically slip resistant?', answer: 'Appearance alone does not establish traction. Review the intended finish and use with the project specifier, and plan for wet weather and ice management.' },
    ], sources: [stoneSources.testing, stoneSources.salts],
  },
  {
    slug: 'natural-stone-veneer-panels-vs-full-bed-stone',
    title: 'Natural Stone Veneer Panels vs Full-Bed Stone: What to Compare',
    metaDescription: 'Compare rigid veneer panels, flexible stone sheets, full-bed stone and manufactured veneer by construction, detailing, samples and total installed scope.',
    keywords: 'stone veneer vs full bed stone, natural stone panels vs manufactured veneer, flexible stone sheets comparison',
    summary: 'Compare stone products by construction and installed scope. Rigid veneer, flexible sheets, full-bed masonry and manufactured veneer have different backing, support, edge and installation requirements.',
    category: 'Veneer & Panels', image: veneerImage, imageAlt: 'Natural stone panel design showing a textured face', productIds: [], stoneCategories: ['mosaic', 'quartzite', 'slate'],
    sections: [
      { id: 'definitions', title: 'Name the construction before comparing price', html: `<p>Full-bed natural stone uses deeper masonry units with the support and attachment designed for that construction. Rigid thin veneer reduces the depth of the natural stone facing and may be supplied as separate pieces or assembled panels. Flexible sheets use a thin natural stone face on a carrier. Manufactured stone veneer is a formed product designed to resemble stone. These names describe different constructions, not interchangeable finishes.</p><p>Ask each bidder to identify what is included: stone face, backing, panel assembly, corners, caps, attachment materials and installation. A low square-foot price is useful only when the compared scopes are clear.</p>` },
      { id: 'comparison', title: 'Use a comparison table in the design meeting', html: `<div class="overflow-x-auto"><table><thead><tr><th>Option</th><th>What to confirm</th><th>Important design question</th></tr></thead><tbody><tr><td>Full-bed natural stone</td><td>Bed depth, support, attachment and mortar</td><td>How is the masonry load carried?</td></tr><tr><td>Rigid thin veneer or panels</td><td>Piece/panel weight, backing and attachment</td><td>How do corners and drainage work?</td></tr><tr><td>Flexible natural stone sheets</td><td>Carrier, adhesive, joints and exposure limits</td><td>Is the complete system approved for this substrate and use?</td></tr><tr><td>Manufactured veneer</td><td>Product system and installation documentation</td><td>Which details and limitations apply to the selected product?</td></tr></tbody></table></div><p>No option should be approved from this table alone. Use it to identify the information needed from the designer, supplier and installer.</p>` },
      { id: 'real-cost', title: 'Compare the installed scope, not just material weight', html: `<p>Veneer may change handling and support requirements, but savings depend on the project. Include substrate preparation, access, scaffolding, attachment, corners, openings, trim, cuts and waste. A highly irregular layout may require more setting-out than a repetitive panel pattern. A curved wall may require a different product construction from a flat facade.</p><p>Make each quotation state whether it covers the visible face only or the full wall package. Ask who provides shop drawings, mock-ups and samples, and who resolves details where the stone meets other materials. This prevents gaps between a material supplier’s scope and a contractor’s assumptions.</p>` },
      { id: 'cold-exposure', title: 'Treat cold-weather performance as an assembly question', html: `<p>For a cold-market exterior, investigate the proposed face, backing, attachment and drainage together. A natural stone face does not establish the performance of every resin, mesh or adhesive combined with it. Full-depth construction also needs a complete water-management and support design.</p><p>Ask for documentation that matches the supplied product and intended exposure. Avoid comparing an interior decorative panel with an exterior masonry product simply because the surface colors look similar. Our <a href="/blog/thin-stone-veneer-cold-climate-exteriors">rigid versus flexible veneer guide</a> explains the first questions to ask.</p>` },
      { id: 'approve', title: 'Approve the product that will actually be delivered', html: `<p>Use a physical sample or mock-up that shows thickness, relief, edges and corners. For random-pattern work, include several pieces and the planned joints. Review how the back of the sample will connect to the specified substrate. Keep the approved drawing and reference sample together with the purchase documents.</p><p>Roop Stone Impex supplies <a href="/thin-stone-veneer">custom rigid stone pieces, flexible panels and decorative veneer patterns</a>. Describe the intended construction in your enquiry so the quotation can be evaluated against the correct alternatives. Confirm all custom dimensions and acceptance criteria before production.</p>` },
    ], faqs: [
      { question: 'Is natural stone veneer the same as manufactured stone?', answer: 'No. Natural veneer has a natural stone face. Manufactured veneer is a formed product. Flexible natural stone sheets also contain a carrier or backing that should be identified.' },
      { question: 'Is veneer always cheaper to install than full-bed stone?', answer: 'Not always. Compare the complete support, preparation, attachment, access and detailing scope for the particular project.' },
    ], sources: [stoneSources.drainage, stoneSources.flexible],
  },
  {
    slug: 'natural-stone-winter-care-deicers-snow-sealers',
    title: 'Winter Care for Natural Stone: Snow, Deicers and Sealers',
    metaDescription: 'Prepare natural stone paving and walls for winter. Plan snow clearing, drainage, deicer selection, cleaning and sealers without relying on frostproof claims.',
    keywords: 'natural stone winter maintenance, deicer sandstone, limestone salt damage, stone patio snow removal',
    summary: 'Winter care starts with removing trapped water and planning snow management. Choose cleaning products and any deicer or sealer for the specific stone and installation; no treatment makes every natural stone winter-proof.',
    category: 'Care & Maintenance', image: careImage, imageAlt: 'Illustration of natural stone surface maintenance', productIds: ['s4', 'l2', 'q2'], stoneCategories: ['sandstone', 'limestone', 'quartzite', 'slate'],
    sections: [
      { id: 'autumn-inspection', title: 'Inspect drainage before the first freeze', html: `<p>Walk the site after rain and identify puddles, blocked outlets and runoff that reaches the stone from roofs or higher ground. Clear leaves and debris from the drainage route. Have damaged joints, loose pieces and deteriorated transitions assessed by the installer before freezing conditions make repairs more difficult.</p><p>Include the base of stone walls in this inspection. Splash, overflowing gutters and snow piled against a wall may repeatedly wet one area. Record photographs so the maintenance team can distinguish an existing issue from a later change. A sound-looking stone face does not show every condition behind it.</p>` },
      { id: 'snow', title: 'Agree how snow will be removed', html: `<p>Discuss compatible tools and equipment with the paving installer. Review blade contact, protective edges and equipment loading for the installed surface. Avoid treating hand-laid natural stone like an unspecified industrial pavement. Raised joints, irregular faces and edges may need a different approach.</p><p>Decide where cleared snow will be stored. Keep drainage outlets open and avoid creating a meltwater path back toward doors or vulnerable wall bases. Remove loose debris before it becomes hidden under snow. Safety and access remain the priority, so the winter plan should be agreed before icy conditions arrive.</p>` },
      { id: 'deicers', title: 'Choose deicers with material compatibility in mind', html: `<p>Do not assume a product described as “safe” for concrete, plants or pets is safe for your stone and mortar. Ask the stone and installation-material suppliers for written guidance on the proposed deicer. Repeated exposure, dosage and moisture conditions can matter alongside the chemical itself.</p><p>The Natural Stone Institute has investigated damage to stone under combinations of deicing chemicals and environmental cycling. That supports a product-specific maintenance decision rather than a universal recommendation for one salt. Discuss any traction material with the maintenance contractor as well, including possible scratching and residue.</p>` },
      { id: 'sealing-cleaning', title: 'Use sealers and cleaners for a defined purpose', html: `<p>A sealer is not a replacement for drainage or a repair for an unsuitable installation. First identify what problem a treatment is meant to address: staining, appearance or a specific maintenance concern. Confirm compatibility with the stone, mortar, backing and exposure, then trial it in an inconspicuous area or on a spare sample.</p><p>For routine care, follow the stone supplier’s cleaning instructions. Avoid selecting a cleaner solely because it removes a stain from another surface. Acidic products can affect calcareous materials, and aggressive treatments may change the finish. Our <a href="/blog/natural-stone-maintenance-sealing-cleaning-guide">general stone care guide</a> covers the broader maintenance conversation.</p>` },
      { id: 'spring', title: 'Make the spring inspection useful', html: `<p>After winter, photograph new surface changes and note where they occur. Is the issue concentrated beside a road, under a downpipe or at a poorly draining joint? Record the maintenance products used and their application history. This helps the supplier and installer investigate rather than guessing from one close-up image.</p><p>Keep a small stock of approved spare pieces where practical and record their batch with the project files. When specifying a new project, read the <a href="/blog/natural-stone-freeze-thaw-climates-usa">freeze–thaw selection checklist</a> so the maintenance plan starts during design, not after the first winter.</p>` },
    ], faqs: [
      { question: 'Can I use rock salt on all natural stone?', answer: 'Do not assume universal compatibility. Check the specific stone, mortar and installation-material recommendations, including the proposed product and application conditions.' },
      { question: 'Should I seal stone every autumn?', answer: 'Use the stone and treatment suppliers’ guidance for the actual surface. Treatment need and renewal depend on the material, exposure and product, rather than a universal annual schedule.' },
    ], sources: [stoneSources.salts, stoneSources.care],
  },
  {
    slug: 'sandstone-vs-limestone-freeze-thaw-paving',
    title: 'Sandstone vs Limestone Paving in Freeze–Thaw Climates',
    metaDescription: 'Compare sandstone and limestone for cold-climate patios by actual product evidence, finish, drainage, maintenance and approved sample range.',
    keywords: 'sandstone vs limestone cold climate, freeze thaw patio stone, limestone paving winter, sandstone paving USA',
    summary: 'Neither sandstone nor limestone is a universal winner for freezing climates. Compare the exact proposed products, their documented properties and the paving assembly, then choose the appearance and maintenance scope that fit the project.',
    category: 'Product Selection', image: limestoneImage, imageAlt: 'Kota Blue natural limestone sample', productIds: ['s4', 's6', 'l2', 'l3'], stoneCategories: ['sandstone', 'limestone'],
    sections: [
      { id: 'comparison-scope', title: 'Compare two specified products, not two broad rock names', html: `<p>A useful comparison is between a named sandstone and a named limestone supplied in agreed dimensions, thickness and finish. Broad labels conceal differences in source, structure, surface and fabrication. Statements that every sandstone is winter-safe or every limestone should be avoided are too broad for a purchase decision.</p><p>Our general <a href="/compare/sandstone-vs-limestone-paving">sandstone versus limestone comparison</a> introduces the design choices. This guide focuses on what changes when the patio will be exposed to repeated wetting and freezing. The final selection should be reviewed for the actual project rather than inherited from another installation.</p>` },
      { id: 'visuals', title: 'Compare appearance at the scale of a patio', html: `<p>Sandstone options such as <a href="/products/s4">Kandla Grey</a> and <a href="/products/s6">Buff</a> offer neutral and warm palettes. Limestone options such as <a href="/products/l2">Kota Blue</a> and <a href="/products/l3">Kota Brown</a> provide another set of tones and textures. View a selection of pieces to understand the range rather than treating one sample as an exact promise.</p><p>Lay the samples beside the building and proposed joint material. Review wet and dry appearance, texture, edge details and the way the pattern meets steps. A finish selected for an interior floor should be assessed separately before it is used outside.</p>` },
      { id: 'technical-comparison', title: 'Put the same questions to both suppliers', html: `<ul><li>Which material and quarry/source does the documentation represent?</li><li>What are the agreed thickness, finish and dimensional tolerances?</li><li>Which physical and environmental test information is available?</li><li>What installation and maintenance conditions apply?</li><li>How will sample variation and batch acceptance be documented?</li></ul><p>A technical value without its method and sample identity is difficult to interpret. Ask the project specifier to assess the relevant evidence, including freezing exposure where appropriate. Do not turn a single absorption number into a complete durability guarantee.</p>` },
      { id: 'maintenance', title: 'Include deicer and cleaning exposure in the choice', html: `<p>Outdoor paving may see deicers, garden chemicals, food spills and cleaning products. Discuss likely exposures before selecting the surface. Some treatments suitable for one material can harm another, and a blanket cleaning routine is a poor substitute for product-specific instructions.</p><p>Ask how the chosen stone and jointing materials should be maintained together. If the property manager requires a particular snow-clearing chemical, bring that requirement into the design discussion early. The <a href="/blog/natural-stone-winter-care-deicers-snow-sealers">winter care guide</a> provides a maintenance checklist.</p>` },
      { id: 'decision', title: 'Use a simple approval sequence', html: `<p>First approve the appearance range. Next agree the paving construction and required documentation. Then coordinate the base, drainage and maintenance plan with the installer. Finally compare quotations on the same supply and delivery basis. This order prevents a low initial material price from settling unresolved installation questions.</p><p>Send your destination, drawings, preferred colors and intended use to Roop Stone Impex. Request samples of the shortlisted <a href="/products?category=sandstone">sandstones</a> and <a href="/products?category=limestone">limestones</a>, with custom thickness and finish requirements stated separately. Confirm acceptance criteria before production.</p>` },
    ], faqs: [
      { question: 'Which is better for a cold US patio: sandstone or limestone?', answer: 'There is no universal category-level answer. Compare the actual products, relevant testing, paving assembly and maintenance exposures.' },
      { question: 'Does a sealer remove the differences between stones?', answer: 'No. Treatments have specific purposes and limitations. They do not replace material selection, technical review or drainage design.' },
    ], sources: [stoneSources.testing, stoneSources.care, stoneSources.salts],
  },
  {
    slug: 'natural-stone-step-treads-copings-cold-climates',
    title: 'Natural Stone Steps and Copings for Cold-Climate Projects',
    metaDescription: 'Specify custom stone step treads, wall caps and pool copings for cold climates, including drawings, finish, support, drainage and sample approval.',
    keywords: 'natural stone step treads USA, stone copings cold climate, sandstone steps winter, custom stone wall caps',
    summary: 'Steps and copings need their own fabrication and installation specification. Confirm geometry, finish, support, drainage and exposure requirements rather than copying the specification for a nearby patio or wall.',
    category: 'Custom Fabrication', image: sandstoneImage, imageAlt: 'Kandla Grey sandstone surface for a custom fabrication discussion', productIds: ['s4', 's6', 'l2', 'q3'], stoneCategories: ['sandstone', 'limestone', 'quartzite'],
    sections: [
      { id: 'different-functions', title: 'Separate steps, wall caps and pool copings in the order', html: `<p>A step tread is a walking surface with a front edge and a defined support condition. A wall cap protects and finishes the top of a wall. A pool coping connects the pool edge to surrounding surfaces and has its own water and maintenance exposure. The same stone color may unify these elements, but the fabrication details should be separate.</p><p>List each element with its quantity, dimensions, thickness, finish and edge profile. Include pieces that turn corners or meet curved geometry. A square-foot allowance for paving does not adequately describe these custom components.</p>` },
      { id: 'drawings', title: 'Use drawings to agree the geometry', html: `<p>For stairs, coordinate the complete stair design with the project designer and local requirements. Identify the tread dimensions, overhang if specified, support, joints and edge profile. Avoid changing the leading edge at fabrication stage without checking its effect on the full stair geometry.</p><p>For caps and copings, identify inside and outside edges, finished faces, corners, returns and any underside details required by the design. Mark where a dimension is measured on a radius. Number unusual pieces so production, packing and installation refer to the same drawing.</p>` },
      { id: 'finish-exposure', title: 'Assess finish and winter exposure together', html: `<p>Review the walking finish for the intended wet conditions. A rough-looking photograph is not a slip test. Snow, frost and ice also require an operational maintenance plan regardless of the stone. Ask the specifier which documentation is appropriate for the actual surface and use.</p><p>Consider where water will collect around tread edges, wall caps and coping joints. The support and drainage design should avoid persistent trapped moisture. For pool settings, identify the proposed water treatment and cleaning products when discussing material compatibility.</p>` },
      { id: 'sampling', title: 'Approve a sample that includes the worked edge', html: `<p>A flat tile sample cannot fully represent a bullnose, eased edge or textured nose. Ask for the proposed edge treatment on a representative sample. Review color on both the face and the worked edge, as fabrication can reveal a different appearance from the natural surface.</p><p>Where several elements will sit close together, approve the palette as a group. Paving, risers and copings can look inconsistent if selected independently from unrelated reference samples. Agree the natural variation range while keeping the technical requirements for each use distinct.</p>` },
      { id: 'delivery', title: 'Plan packing and site handling for custom pieces', html: `<p>Ask for drawing numbers and piece identifiers on the packing list. Discuss crate organization, protection of worked edges and the unloading equipment available at the receiving site. Large or unusual pieces need a handling plan that matches their dimensions and weight.</p><p>Roop Stone Impex offers custom stone fabrication. Send drawings and destination details with the enquiry, then confirm the material, technical submission and sample approval before production. Read the <a href="/blog/natural-stone-freeze-thaw-climates-usa">cold-climate selection guide</a> and <a href="/blog/natural-stone-winter-care-deicers-snow-sealers">winter care checklist</a> alongside the fabrication schedule.</p>` },
    ], faqs: [
      { question: 'Can I order custom tread and coping sizes?', answer: 'Yes, custom fabrication can be discussed with Roop Stone Impex. Supply drawings, dimensions, thickness, edge profiles, quantities and intended exposure for quotation and approval.' },
      { question: 'Can paving thickness be reused for a stair tread?', answer: 'Do not assume it can. The tread’s geometry, support, loading and fabrication need a separate project specification.' },
    ], sources: [stoneSources.testing],
  },
  {
    slug: 'import-natural-stone-india-usa-buyers-checklist',
    title: 'Importing Natural Stone from India to the USA: A Buyer’s Checklist',
    metaDescription: 'Prepare a US natural stone import enquiry with product specifications, sample approvals, packing, freight scope and a clear landed-cost worksheet.',
    keywords: 'import natural stone India USA, Indian stone supplier USA, stone veneer import, stone container buyer checklist',
    summary: 'Start a US stone import with a precise product schedule and agreed commercial scope. Separate stone and fabrication from freight, destination charges and customs-related costs, and confirm current import requirements with your broker.',
    category: 'Export & Logistics', image: packingImage, imageAlt: 'Illustration of natural stone packing for export', productIds: ['q4', 's4', 's6', 'sl4'], stoneCategories: ['quartzite', 'sandstone', 'limestone', 'slate', 'mosaic'],
    sections: [
      { id: 'product-schedule', title: 'Create a product schedule that can survive handovers', html: `<p>Give every quote line a product name, stone variety, format, dimensions, thickness, finish, edge detail and quantity. Distinguish square feet from linear feet and pieces. Veneer flats, corners, treads and caps should not be combined into one unclear area allowance.</p><p>For flexible panels, identify the backing and intended substrate. For rigid or random-pattern veneer, identify the construction and layout expectations. State the destination and use, especially if material will be exposed to freezing conditions. The <a href="/blog/thin-stone-veneer-cold-climate-exteriors">veneer specification guide</a> can help organize those questions.</p>` },
      { id: 'samples-contract', title: 'Agree samples, documentation and acceptance before production', html: `<p>Approve the expected natural variation using a sample range or mock-up. Record dimensions and tolerances on drawings, and agree which technical documents should accompany the order. If additional testing is required, settle the sampling and approval process before committing to the production schedule.</p><p>Keep the product schedule, reference sample photographs, drawing revisions and commercial quotation together. A message saying “same as the sample” is less useful than a documented record of which sample, construction and finish were approved.</p>` },
      { id: 'cost-scope', title: 'Build a landed-cost worksheet without assuming the duty rate', html: `<p>Separate material, custom fabrication, export packing, origin handling, ocean freight, insurance, destination handling, customs-related costs and inland delivery. Ask the freight provider and licensed customs broker to confirm which costs and responsibilities apply to the agreed shipment terms. Duty rates and trade measures should be checked for the actual product and entry date.</p><p>Our <a href="/pricing">FOB price guide</a> is a material-planning tool, not a complete US delivered-cost quotation. Confirm the named port, delivery term and included services in the commercial quotation. Do not estimate tariffs from a generic label such as “natural stone”; construction and processing can affect the classification question.</p>` },
      { id: 'packing', title: 'Check packing and unloading before the container is booked', html: `<p>Agree crate identification, quantities, piece protection, packing photographs and the packing list. Ask the supplier and logistics team to confirm compliant wood packaging where regulated wood is used. USDA APHIS requires regulated wood packaging entering the United States to meet ISPM 15 treatment and certification requirements.</p><p>Tell the receiving warehouse or site what is arriving and confirm suitable unloading equipment. Plan where crates can be stored without blocking access. For phased installations, discuss packing sequence so one needed corner piece is not buried under material for a later elevation.</p>` },
      { id: 'arrival', title: 'Plan receipt and inspection as part of the order', html: `<p>Arrange who checks quantities, labels, visible condition and documentation on arrival. Photograph the packing and any concerns before moving or installing disputed material. Follow the agreed commercial and <a href="/return-policy">claims procedure</a>, and keep the freight and insurance contacts available.</p><p>For projects in northern US states, allow time between receipt and the intended installation season for inspection, sample checks and contractor coordination. Freight schedules are shipment-specific; request a current estimate rather than treating an online transit range as a delivery promise. Send the completed product schedule to <a href="/contact#query-form">Roop Stone Impex</a> for a project quotation.</p>` },
    ], faqs: [
      { question: 'Does an FOB price include delivery to a US jobsite?', answer: 'Do not assume so. Confirm the named port, shipment terms, included services and destination/inland costs in the quotation.' },
      { question: 'What tariff applies to Indian natural stone?', answer: 'Have your customs broker confirm current classification, origin treatment, duties and other measures for the actual product and entry date. This guide does not quote a universal tariff.' },
    ], sources: [stoneSources.wood, { title: 'US Customs and Border Protection: importer and broker guidance', url: 'https://www.help.cbp.gov/s/article/Article-1390?language=en_US' }],
  },
];

export function guideContent(guide: ColdClimateGuide): string {
  return guide.sections.map(s => `<h2 id="${s.id}">${s.title}</h2>${s.html}`).join('\n');
}
